-- Grade 9 Media Arts, Term 2: Animation (5 lessons, 50 quiz questions).
-- Generated by scripts/build-term2-g9.mjs. Paste into the Supabase SQL editor and run.
-- Safe to run again: the module is only created if missing, so it will NOT undo
-- a lock or unlock you set on the Modules page. Lesson text and quizzes are refreshed.
-- The module is created LOCKED. Unlock Term 2 on the teacher Modules page when ready.

begin;



delete from public.quizzes where activity_id in ($q$G9-A2.1$q$, $q$G9-A2.2$q$, $q$G9-A2.3$q$, $q$G9-A2.4$q$, $q$G9-A2.5$q$);

select (select count(*) from public.modules where module_id = 'G9-M2') as modules, (select count(*) from public.activities where module_id = 'G9-M2') as lessons, (select count(*) from public.quizzes where module_id = 'G9-M2') as quiz_questions;

commit;
